<?php
declare(strict_types=1);

/*
 * Admin-controlled ONE-TIME Access Keys for Create Account.
 *
 * - Generated by the admin (Settings -> Access Key Generate), each key bound to exactly ONE username.
 * - Required on Create Account: valid only together with its bound username, and only once.
 * - Everything (generation, binding, validation, consumption) is enforced server-side in MySQL.
 *   See api/auth-register.php: the key row is locked (SELECT ... FOR UPDATE) inside the same transaction that
 *   creates the user and marks the key used, so two simultaneous signups can never share one key.
 * - Existing users and the login flow are never touched.
 */

const ACCESS_KEY_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';   // Base32: no 0/O/1/I confusion
const ACCESS_KEY_LENGTH   = 16;                                    // 16 x 5 bits = 80 bits of randomness
const ACCESS_KEY_REJECTED_MESSAGE = 'Invalid Access Key for this username, or the key has already been used.';

/** Thrown inside the registration transaction when the key may not be used (always rolls everything back). */
class AccessKeyRejected extends RuntimeException
{
}

/** 16 random characters from a CSPRNG (256 is divisible by 32, so "& 31" is perfectly uniform). */
function access_key_generate(): string
{
    $bytes = random_bytes(ACCESS_KEY_LENGTH);
    $out = '';
    for ($i = 0; $i < ACCESS_KEY_LENGTH; $i++) {
        $out .= ACCESS_KEY_ALPHABET[ord($bytes[$i]) & 31];
    }
    return $out;
}

/** XXXX-XXXX-XXXX-XXXX (display only; the stored/compared form has no dashes). */
function access_key_format(string $key): string
{
    return implode('-', str_split($key, 4));
}

function access_key_mask(string $key): string
{
    return 'XXXX-XXXX-XXXX-' . substr($key, -4);
}

/** Accepts any case, spaces and dashes. Returns the canonical 16-char key, or null if it can never be valid. */
function access_key_normalize(string $raw): ?string
{
    $k = strtoupper((string)preg_replace('/[\s\-]+/', '', $raw));
    return preg_match('/^[A-Z2-7]{16}$/', $k) === 1 ? $k : null;
}
